  /// Creates a SetConfigDisplayCurrencyResponse from already-decoded fields.
  const SetConfigDisplayCurrencyResponse({
    this.code,
    this.raw = const {},
  });

  /// Decodes a JSON object into a SetConfigDisplayCurrencyResponse. Every field is read tolerantly: one that is absent or has an unexpected type decodes to `null` (or an empty collection).
  factory SetConfigDisplayCurrencyResponse.fromJson(
          Map<String, Object?> json) =>
      SetConfigDisplayCurrencyResponse(
        code: json.optString('code'),
        raw: json,
      );

  /// ISO 4217 compliant display currency code
  final String? code;

  /// The whole decoded object, for fields not promoted to a property.
  final Map<String, Object?> raw;

  /// Encodes the object as JSON, omitting absent fields.
  Map<String, Object?> toJson() => {
        if (code != null) 'code': code!,
      };
}
